const tabId = 2136412435;
const engineerInfo = await browserjs(tabId, () => {
  const select = document.querySelector('select');
  if (!select) return "No select found";

  // Find Engineer option
  const options = Array.from(select.options);
  const engOpt = options.find(o => o.text.includes('Engineer'));
  if (engOpt) {
    select.value = engOpt.value;
    select.dispatchEvent(new Event('change', { bubbles: true }));
  }

  const resultDiv = document.querySelector('.classification-result, #classification-result, .mpeg-join-classification-result, .mpeg-general-forms');
  return {
    selectedValue: select.value,
    selectedText: engOpt?.text,
    content: document.querySelector('.mpeg-join-classification-info')?.innerText || document.body.innerText.slice(3000, 4500)
  };
});
console.log(JSON.stringify(engineerInfo, null, 2));

